/* steers the moby toward its target: queries the path, eases x/y, then turns to face the heading */
int follow_plasmabot_path(char *moby) {
    float a[4];
    float b[4];
    float c[4];
    struct PlasmabotVars *data = (struct PlasmabotVars *)((Moby *)moby)->pvars;
    int r = Spline_AdvanceByDistance(oltanis_paths[data->path_a], a, &data->path_step, &data->path_t, 0,
                              *(float *)&plasmabot_path_speed * g_frame_time * data->scale);
    float ang;
    float k;
    float m;
    qcopy(b, &((Moby *)moby)->pos);
    Spring(&((Moby *)moby)->pos.x, &data->spring_x, a[0], 0.01f, 0.2f, 0.0f);
    Spring(&((Moby *)moby)->pos.y, &data->spring_y, a[1], 0.01f, 0.2f, 0.0f);
    FastVecSub(c, a, b);
    ang = fast_atan2(c[0], c[1]);
    k = g_frame_time_sq * 12.566371f;
    m = g_frame_time * 6.2831855f;
    SteerAngleWithVelocity_r(&((Moby *)moby)->rot.z, ang, &data->turn_vel, k, k, m);
    return r != 0;
}
