/* Moby update for a falling debris particle. */
void update_spinning_moby_with_particle_trail(struct MobyDf *moby) {
    float *velocity = (float *)moby->pvars;
    int i;
    int n;
    int alpha;
    int color;
    float size;
    float absolute_velocity;
    unsigned char *particle;
    unsigned char *fade;

    if (random_integer_below(2) != 0) {
        AddDrawCallback((void (*)(void))draw_spinning_debris, moby);
    }
    FastVecAdd(&moby->pos, &moby->pos, velocity);
    absolute_velocity = FastAbsF(velocity[0]);
    if ((*(float *)&spinning_debris_drag_min_speed) * frame_scale < absolute_velocity) {
        velocity[0] *= ((*(float *)&spinning_debris_drag) - 1.0f) * frame_scale + 1.0f;
    }
    absolute_velocity = FastAbsF(velocity[1]);
    if ((*(float *)&spinning_debris_drag_min_speed) * frame_scale < absolute_velocity) {
        velocity[1] *= ((*(float *)&spinning_debris_drag) - 1.0f) * frame_scale + 1.0f;
    }
    if (velocity[2] > 0.0f) {
        velocity[2] *= ((*(float *)&spinning_debris_drag) - 1.0f) * frame_scale + 1.0f;
    }
    velocity[2] -= (*(float *)&spinning_debris_gravity) * g_frame_scale_sq;
    moby->rot.x = FastAddRots(moby->rot.x, velocity[4]);
    moby->rot.y = FastAddRots(moby->rot.y, velocity[5]);
    moby->rot.z = FastAddRots(moby->rot.z, velocity[6]);

    if (moby->pos.x < 2.0f || 1021.0f < moby->pos.x ||
        moby->pos.y < 2.0f || 1021.0f < moby->pos.y ||
        moby->pos.z < 2.0f || 1021.0f < moby->pos.z) {
        DeleteMoby((struct Moby *)moby);
        return;
    }
    if (fast_dec_timer(velocity + 8) != 0 || coll_sphere(0.5f, &moby->pos, 0, *(void **)(velocity + 9)) != 0) {
        spawn_explosion((struct Moby *)moby, velocity, &moby->pos, 0.0f, 0.0f, 5, 2, 4,
                             1.0f, 0.5f, 9.0f, 1.0f, 0, 15.0f, 1, 5, -1, 0);
        coll_sphere(1.0f, &moby->pos, 0, *(void **)(hero_globals_base + 0x2E9D));
        DeleteMoby((struct Moby *)moby);
        return;
    }
    PartType21Spawn(&moby->pos, oltanis_zero_vector, 0x4F007FFF, 0x1FFFFFFF,
                         rand_range(scale_ticks(10), scale_ticks(20)), 1, 60000.0f);
    for (i = 0; i < 2; i++) {
        n = random_integer_below(6);
        if (random_integer_below(2) != 0) n = -n;
        size = random_float_between(40000.0f, 100000.0f);
        color = rand_range(0x30, 0xFF);
        alpha = 0x60000000;
        particle = (unsigned char *)PartType23Spawn(&moby->pos, 0.025f, 1.0f, 1.0f, n,
                                        oltanis_zero_vector, size,
                                        color | ((color << 16) | ((color << 8) | alpha)));
        if (particle != 0) {
            particle[3] = 0x44;
            fade = particle + 0x20;
            *(short *)(particle + 0xA) = scale_ticks(0x3C);
            *(int *)(fade + 4) = 2;
            fade[0xA] = 0x60;
            fade[0xB] = particle[0xA];
        }
    }
}
