/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/entities/002b17d8.c, FUN_L14_002feca8. */
void emit_moby_offset_particles(Moby *m) {
    float off[4];
    float pos[4];
    int i;
    int j;
    int n;
    int life;
    float size;
    FastVecScale(off, &m->rot_row0, (*(float *)&offset_particles_first_offset_x));
    FastVecAdd(pos, &m->pos, off);
    FastVecScale(off, &m->rot_row2, (*(float *)&offset_particles_first_offset_y));
    FastVecAdd(pos, pos, off);
    for (i = 0; i < 2; i++) {
        P_eca8 *part;
        T_eca8 *tail;
        n = random_integer_below(0x10);
        part = PartType23Spawn(pos, 0.2f, 1.0f, 0.9f, random_integer_below(2) == 0 ? n : -n, oltanis_zero_vector, 100000.0f, (*(int *)&offset_particles_color));
        if (part) {
            tail = &part->tail;
            part->hA = scale_ticks(0xC);
            tail->w4 = 2;
            tail->bA = 0x7F;
            tail->bB = part->hA;
        }
    }
    FastVecScale(off, &m->rot_row0, (*(float *)&offset_particles_second_offset_x));
    FastVecAdd(pos, &m->pos, off);
    FastVecScale(off, &m->rot_row2, (*(float *)&offset_particles_second_offset_y));
    FastVecAdd(pos, pos, off);
    n = 0x10;
    life = scale_ticks(2);
    size = 80000.0f;
    for (j = 0; j < 3; j++) {
        P_eca8 *part;
        T_eca8 *tail;
        part = PartType23Spawn(pos, 0.05f, 1.0f, 1.0f, n, oltanis_zero_vector, size, 0x7FFFFFFF);
        if (part) {
            tail = &part->tail;
            part->hA = life;
            part->b8 = random_integer_below(0xFF);
            tail->w4 = 2;
            tail->bA = 0x7F;
            tail->bB = part->hA;
        }
        n = -n;
        size -= 20000.0f;
        life *= 2;
    }
}
