/* Init of a 32-point strip (rope/beam style) moby. */
void start_vendor_beam_pulse(char *moby) {
    D_02C80 *beam = ((D_02C80 *)((Moby *)moby)->pvars);
    Vq_02C80 path[32];
    Vq_02C80 path_steps[32];
    Vq_02C80 work, delta;
    Vq_02C80 matrix[4];
    VendorBeamFrame *frame;
    float length;
    int low, high, duration;
    int i, j, k, branch;

    frame = (VendorBeamFrame *)((beam->idx << 7) + (int)oltanis_clip_volumes);
    {
        int ticks = (*(int *)&vendor_beam_min_ticks);
        frame->origin.f[3] = 1.0f;
        low = scale_ticks(ticks);
    }
    high = scale_ticks((*(int *)&vendor_beam_max_ticks));
    duration = rand_range(low, high);
    beam->s12 = (short)duration;
    beam->r620 = (short)duration;
    length = FastVecLength(oltanis_clip_volumes + (beam->idx << 7) + 0x10);
    length = length + length;

    for (i = 0; i < 32; i++) {
        float y_offset = IntToFloat(i);
        float last = IntToFloat(0x1F);
        float y;
        y_offset = y_offset / last;
        y_offset = (0.5f - y_offset) * length;
        if (i < 3 || i > 28) {
            clear_u64_value(&path[i]);
            clear_u64_value(&path_steps[i]);
        } else {
            rand_vec(&path[i], 0.0f, *(float *)&vendor_beam_jitter_radius);
            rand_vec(&path_steps[i], 0.0f, *(float *)&vendor_beam_jitter_speed * g_frame_time);
        }
        y = path[i].y;
        path[i].w = 1.0f;
        path[i].y = y + y_offset;
    }

    for (j = 0; j < 32; j++) {
        if (j == 0 || j == 31) {
            qcopy(&beam->pts[j], &path[j]);
            qcopy(&beam->off[j], &path_steps[j]);
        } else {
            FastVecAdd(&work, &path[j - 1], &path[j]);
            FastVecAdd(&work, &work, &path[j + 1]);
            FastVecScale(&beam->pts[j], &work, 0.333f);
            FastVecAdd(&work, &path_steps[j - 1], &path_steps[j]);
            FastVecAdd(&work, &work, &path_steps[j + 1]);
            FastVecScale(&beam->off[j], &work, 0.333f);
        }
    }

    for (branch = 0; branch < 4; branch++) {
        int start;
        float spread = (*(float *)&vendor_beam_jitter_radius);
        rand_vec(&work, spread, spread);
        start = truncate_float_to_s32(random_float_between((float)branch * 6.0f, (float)(branch + 1) * 6.0f)) + 4;
        beam->cnt[branch] = (unsigned char)start;
        qcopy(&beam->a[0][branch], &beam->pts[start]);
        qcopy(&beam->b[0][branch], &beam->off[start]);
        for (k = 1; k < 4; k++) {
            rand_vec(&delta, 0.1f, 0.1f);
            rand_vec(&beam->b[k][branch], 0.0f, (*(float *)&vendor_beam_jitter_speed) * g_frame_time);
            FastVecAdd(&beam->a[k][branch], &beam->a[k - 1][branch], &work);
            FastVecAdd(&beam->a[k][branch], &beam->a[k][branch], &delta);
        }
    }

    if (vec_distance_xy(oltanis_clip_volumes + (beam->idx << 7) + 0x30, oltanis_camera_pos) >= 4.0f) {
        int s17;
        int l;
        euler_to_matrix(matrix, oltanis_clip_volumes + (beam->idx << 7) + 0x70);
        qcopy(&matrix[3], (char *)((beam->idx << 7) + (int)oltanis_clip_volumes) + 0x30);
        for (l = 0; l < 32; l += 8) {
            int n;
            Vq_02C80 *p = &beam->pts[l];
            transform_vector(&work, p, matrix);
            qcopy(&delta, &p[32]);
            delta.w = (*(float *)&vendor_beam_spark_step_w_gp);
            s17 = random_integer_below(2) ? (*(int *)&vendor_beam_spark_tex_a) : (*(int *)&vendor_beam_branch_end_spark_color_gp);
            n = scale_ticks(random_integer_below(10) + 20);
            PartType02Spawn(&work, &delta, &delta, (*(int *)&vendor_beam_spark_color_start), (*(int *)&vendor_beam_spark_color_end), l >> 1, 15, n, s17);
        }
        for (k = 0; k < 2; k++) {
            int n, unused_color;
            transform_vector(&work, &beam->a[3][k], matrix);
            qcopy(&delta, &beam->b[3][k]);
            delta.w = (*(float *)&vendor_beam_spark_step_w_gp);
            unused_color = random_integer_below(2) ? (*(int *)&vendor_beam_spark_tex_a) : (*(int *)&vendor_beam_branch_end_spark_color_gp);
            n = scale_ticks(random_integer_below(10) + 20);
            PartType02Spawn(&work, &delta, &delta, (*(int *)&vendor_beam_spark_color_start), (*(int *)&vendor_beam_spark_color_end), beam->cnt[k] >> 1, 15, n, (*(int *)&vendor_beam_branch_end_spark_color_gp));
        }
    }
}
extern int FastTweenColor(int, int, float);
extern short vendor_beam_fade_mid_ticks;
