/* Slot update of moby class 1331: state 0 clears the two slot arrays, state 1 services the pending slots and frees a slot whose moby has died. Level 14 relative of func_L00_002E32A0. */
void update_beam_slots(Moby *m) {
    int i;
    int j;
    int n;
    int st;

    switch (m->state) {
    case 0:
        for (j = 0; j < 3; j++) {
            oltanis_beam_slot_states[j] = 0;
            oltanis_beam_slot_owners[j] = 0;
        }
        m->state = 1;
        m->update_dist = 0xFF;
        break;
    case 1:
        n = 0;
        for (i = 0; i < 3; i++) {
            st = oltanis_beam_slot_states[i];
            if (st == 1) {
                if (((signed char *)oltanis_beam_slot_owners[i])[0x20] < 0) {
                    oltanis_beam_slot_states[i] = 0;
                    oltanis_beam_slot_owners[i] = 0;
                }
            } else if (st == 4) {
                release_beam_slot(i);
            } else if (st != 0) {
                n++;
                update_slot_panes_and_effects(oltanis_beam_slot_owners[i], i);
                oltanis_beam_slot_states[i] = 4;
            }
        }
        if (n != 0) {
            AddDrawCallback(draw_active_beam_slots, m);
        }
        break;
    }
}
